<!--
 * 消息模板表单组件
 *
 * @path apps/message-web/src/views/template/template-form.vue
 * @author ydsz-team
 * @since 1.0.0
 * @modified 4.1.0 由脚手架 CRUD 重写为契约 API：模板新增/编辑表单（TemplateCreateDTO）提交 create/update。
-->
<script lang="ts" setup>
/**
 * 消息模板（表单组件）
 * <p>消费后端契约 TemplateController#create/update（src/api/template.ts，auto-generated by bash/gen-contract.py）：
 * 按 TemplateCreateDTO 字段（templateCode/channel/category/sceneCode/subject/content/provider 等）填写，
 * 新增调 create()、编辑调 update({id}, data)，成功后 emit('success') 并关闭弹窗。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import { useYDSZModal } from '@ydsz/common-ui';
import { ElForm, ElFormItem, ElInput, ElMessage } from 'element-plus';
import { computed, reactive, ref } from 'vue';

import { create, update } from '#/api/template';
import type { MsgTemplateVO } from '#/api/models';

const emit = defineEmits<{ success: [] }>();

const formRef = ref();
const isEdit = ref(false);

/** 模板表单状态（字段对应 TemplateCreateDTO） */
interface TemplateFormState {
  id: string;
  templateCode: string;
  channel: string;
  locale: string;
  version: string;
  category: string;
  sceneCode: string;
  subject: string;
  content: string;
  provider: string;
  providerKey: string;
  signName: string;
  description: string;
}

const formData = reactive<TemplateFormState>({
  id: '',
  templateCode: '',
  channel: '',
  locale: '',
  version: '',
  category: '',
  sceneCode: '',
  subject: '',
  content: '',
  provider: '',
  providerKey: '',
  signName: '',
  description: '',
});

const rules = {
  templateCode: [{ required: true, message: '请输入模板编码', trigger: 'blur' }],
  content: [{ required: true, message: '请输入模板内容', trigger: 'blur' }],
};

const [Modal, modalApi] = useYDSZModal({
  onOpenChange: (isOpen: boolean) => {
    if (!isOpen) return;
    const data = modalApi.getData<{ record?: MsgTemplateVO }>();
    if (data?.record) {
      isEdit.value = true;
      Object.assign(formData, {
        id: data.record.id ?? '',
        templateCode: data.record.templateCode ?? '',
        channel: data.record.channel ?? '',
        locale: data.record.locale ?? '',
        version: data.record.version ?? '',
        category: data.record.category ?? '',
        sceneCode: data.record.sceneCode ?? '',
        subject: data.record.subject ?? '',
        content: data.record.content ?? '',
        provider: data.record.provider ?? '',
        providerKey: data.record.providerKey ?? '',
        signName: data.record.signName ?? '',
        description: data.record.description ?? '',
      });
    } else {
      isEdit.value = false;
      Object.assign(formData, {
        id: '',
        templateCode: '',
        channel: '',
        locale: '',
        version: '',
        category: '',
        sceneCode: '',
        subject: '',
        content: '',
        provider: '',
        providerKey: '',
        signName: '',
        description: '',
      });
    }
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch {
      return;
    }
    modalApi.lock();
    try {
      const payload = {
        templateCode: formData.templateCode,
        channel: formData.channel || undefined,
        locale: formData.locale || undefined,
        version: formData.version || undefined,
        category: formData.category || undefined,
        sceneCode: formData.sceneCode || undefined,
        subject: formData.subject || undefined,
        content: formData.content,
        provider: formData.provider || undefined,
        providerKey: formData.providerKey || undefined,
        signName: formData.signName || undefined,
        description: formData.description || undefined,
      };
      if (isEdit.value) {
        await update({ id: formData.id }, payload);
        ElMessage.success('更新成功');
      } else {
        await create(payload);
        ElMessage.success('创建成功');
      }
      emit('success');
      modalApi.close();
    } finally {
      modalApi.unlock();
    }
  },
});

const title = computed(() => (isEdit.value ? '编辑模板' : '新增模板'));
</script>
<template>
  <Modal :title="title">
    <ElForm ref="formRef" :model="formData" :rules="rules" label-width="100px" label-position="right">
      <ElFormItem label="模板编码" prop="templateCode">
        <ElInput v-model="formData.templateCode" placeholder="请输入模板编码" :disabled="isEdit" />
      </ElFormItem>
      <ElFormItem label="通道" prop="channel">
        <ElInput v-model="formData.channel" placeholder="请输入通道，如 SMS/EMAIL/IN_APP" />
      </ElFormItem>
      <ElFormItem label="分类" prop="category">
        <ElInput v-model="formData.category" placeholder="请输入分类（可为空）" />
      </ElFormItem>
      <ElFormItem label="场景编码" prop="sceneCode">
        <ElInput v-model="formData.sceneCode" placeholder="请输入场景编码（可为空）" />
      </ElFormItem>
      <ElFormItem label="主题" prop="subject">
        <ElInput v-model="formData.subject" placeholder="请输入主题（可为空）" />
      </ElFormItem>
      <ElFormItem label="内容" prop="content">
        <ElInput v-model="formData.content" type="textarea" :rows="4" placeholder="请输入模板内容" />
      </ElFormItem>
      <ElFormItem label="供应商" prop="provider">
        <ElInput v-model="formData.provider" placeholder="请输入供应商（可为空）" />
      </ElFormItem>
      <ElFormItem label="供应商键" prop="providerKey">
        <ElInput v-model="formData.providerKey" placeholder="请输入供应商模板键（可为空）" />
      </ElFormItem>
      <ElFormItem label="签名" prop="signName">
        <ElInput v-model="formData.signName" placeholder="请输入签名（可为空）" />
      </ElFormItem>
      <ElFormItem label="语言" prop="locale">
        <ElInput v-model="formData.locale" placeholder="请输入语言（可为空）" />
      </ElFormItem>
      <ElFormItem label="版本" prop="version">
        <ElInput v-model="formData.version" placeholder="请输入版本（可为空）" />
      </ElFormItem>
      <ElFormItem label="描述" prop="description">
        <ElInput v-model="formData.description" type="textarea" :rows="2" placeholder="请输入描述（可为空）" />
      </ElFormItem>
    </ElForm>
  </Modal>
</template>